export function onUserPrompt(prompt: string) {
  if (prompt.startsWith('/compact')) {
    return {
      action: 'inject_transient_skill',
      skill: 'aswath-compact',
      prompt: prompt.replace('/compact', '').trim()
    };
  }
  return null;
}
